using System.Collections.Generic;
using System.Xml;

namespace SharpOnvifCommon.Xml
{
    /// <summary>
    /// What a generated contract writes itself with.
    /// </summary>
    /// <remarks>
    /// Serialization is compiled into the generated types rather than discovered by reflection, so
    /// every contract drives this interface directly, line by line. Only the interface is
    /// generated: how an element actually reaches the wire, and what the lexical form of a value
    /// is, are somebody's implementation.
    /// <para>
    /// The conversions live here rather than in a class of their own because a contract always has
    /// a writer to hand when it is writing, and putting them anywhere else would mean naming a
    /// type the generated code is not supposed to know.
    /// </para>
    /// </remarks>
    public interface IXmlWriter
    {
        /// <summary>The writer underneath, for content this interface does not describe.</summary>
        XmlWriter Xml { get; }

        void WriteStartElement(string ns, string name);

        void WriteEndElement();

        void WriteElementString(string ns, string name, string value);

        void WriteEmptyElement(string ns, string name);

        /// <summary>
        /// Writes an element holding a contract, naming its type with xsi:type when the value is
        /// of a type derived from the declared one.
        /// </summary>
        void WriteElement(string ns, string name, OnvifContract value, string declaredTypeNamespace, string declaredTypeName);

        /// <summary>Writes a contract's attributes and children into the element already open.</summary>
        void WriteContent(OnvifContract value);

        void WriteNil(string ns, string name);

        void WriteElementQualifiedName(string ns, string name, XmlQualifiedName value);

        /// <summary>Renders a qualified name as a prefixed string, declaring the prefix if needed.</summary>
        string QualifiedNameToString(XmlQualifiedName value);

        void WriteAttributeString(string ns, string name, string value);

        void WriteText(string value);

        void WriteAnyElement(XmlNode node);

        void WriteAny(XmlElement[] elements);

        void WriteAny(XmlNode[] nodes);

        /// <summary>The lexical form of a value, as its schema type defines it.</summary>
        string ToXml(bool value);

        string ToXml(sbyte value);
        string ToXml(byte value);
        string ToXml(short value);
        string ToXml(ushort value);
        string ToXml(int value);
        string ToXml(uint value);
        string ToXml(long value);
        string ToXml(ulong value);
        string ToXml(decimal value);
        string ToXml(float value);
        string ToXml(double value);
        string ToXml(System.DateTime value);
        string ToXml(byte[] value);

        /// <summary>The xs:date form, which carries no time.</summary>
        string ToDateString(System.DateTime value);

        /// <summary>The xs:time form, which carries no date.</summary>
